def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    if N <= 0 or not grid_values or not grid_values[-1]:
        return 0

    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values[:-1]:
        grid[x][y] = value

    # Initialize the first row and first column
    for i in range(1, N):
        grid[0][i] += grid[0][i - 1]
        grid[i][0] += grid[i - 1][0]

    # Fill the rest of the grid using dynamic programming
    for i in range(1, N):
        for j in range(1, N):
            grid[i][j] += max(grid[i - 1][j], grid[i][j - 1])

    # The maximum sum of values collected on the two paths is the maximum value in the bottom-right corner
    return max(grid[-1])

