def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1.")

    largest_factor = -1

    # Check for factors from 2 up to the square root of n
    for i in range(2, int(math.sqrt(n)) + 1):
        while n % i == 0:
            largest_factor = i
            n //= i

    # If n is a prime number greater than 2
    if n > 2:
        largest_factor = n

    return largest_factor

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x or k < 1 or x < 1:
        return 0

    # Initialize a 2D array to store the number of ways to partition
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base case: There's one way to partition 0 into 0 parts
    dp[0][0] = 1

    # Fill the dp array
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if i >= j * x:
                dp[i][j] = dp[i - j * x][j - 1] + dp[i - 1][j]

    return dp[n][k]

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n <= 0 or last < 0 or last > n:
        return 0

    if last in memo:
        return memo[last]

    count = 0
    for i in range(1, last + 1):
        if i <= n:
            count += count_sequences(n, i, memo)

    memo[last] = count
    return count

