def generate_numbers(n, rules) -> int:
    if not rules:
        return 1  # The original number itself is a valid transformation

    # Convert the number to a list of digits
    digits = [int(d) for d in str(n)]
    queue = deque(digits)
    visited = set(digits)

    while queue:
        current = queue.popleft()
        for rule in rules:
            if current == rule[0]:
                new_digit = rule[1]
                if new_digit not in visited:
                    visited.add(new_digit)
                    queue.append(new_digit)

    return len(visited)

