def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a 2D array to store the maximum value for each time and herb combination
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    # Iterate through each herb and time
    for i in range(1, M + 1):
        for j in range(1, T + 1):
            # If the herb can be picked within the current time
            if herbs[i - 1][0] <= j:
                # Calculate the maximum value by either picking the herb or not picking it
                dp[i][j] = max(dp[i - 1][j], herbs[i - 1][1] + dp[i - 1][j - herbs[i - 1][0]])
            else:
                # If the herb cannot be picked, take the value from the previous time
                dp[i][j] = dp[i - 1][j]

    # The maximum value for the given time limit and number of herbs
    return dp[M][T]

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1

    for i in range(n):
        for j in range(m, a[i] - 1, -1):
            dp[j] = (dp[j] + dp[j - a[i]]) % MOD

    return dp[m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    if not key.isalpha() or not ciphertext.isalpha():
        raise ValueError("Key and ciphertext must consist only of alphabetic characters.")

    key_length = len(key)
    plaintext = ""

    for i, char in enumerate(ciphertext):
        if char.isalpha():
            shift = ord(key[i % key_length]) - ord('A') if char.isupper() else ord(key[i % key_length]) - ord('a')
            decrypted_char = chr((ord(char) - ord('A') - shift) % 26 + ord('A')) if char.isupper() else chr((ord(char) - ord('a') - shift) % 26 + ord('a'))
            plaintext += decrypted_char
        else:
            plaintext += char

    return plaintext

def mod_inverse(a, b):
    if b == 0:
        raise ValueError("Modulus cannot be zero.")

    x, y, u, v = 1, 0, 0, 1
    while b != 0:
        q = a // b
        a, b = b, a % b
        x, u = u, x - q * u
        y, v = v, y - q * v

    if a != 1:
        return None

    return x % b

