    if not heights:
        return 0

    n = len(heights)
    left = 0
    right = n - 1
    count = 0

    while left < right:
        if heights[left] < heights[right]:
            left += 1
        else:
            right -= 1
            count += 1

    return count

def min_groups(w, n, prices):
    if n == 0:
        return 0

    prices.sort()
    total_price = 0
    groups = 0

    for price in prices:
        total_price += price
        if total_price > w:
            groups += 1
            total_price = price

    return groups + 1

def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("Number of disc pairs must be at least 1.")

    # Base cases
    if n == 1:
        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14

    # Recursive relation
    total_moves = 2 * (2 ** n - 1)

    return total_moves

def total_smoked_cigarettes(n, k):
    if n < 0 or k < 0:
        raise ValueError("Number of cigarettes and butts must be non-negative.")
    total_cigarettes = n
    while total_cigarettes >= k:
        total_cigarettes += total_cigarettes // k
    return total_cigarettes
